 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    # Source marker is the one adjacent to the colored motif; translate that
    # motif so its marker lands on the other marker, retaining the source.
    def nearby(r, c):
        return sum(1 for dr in range(-2, 3) for dc in range(-2, 3)
                   if (dr or dc) and 0 <= r+dr < h and 0 <= c+dc < w
                   and grid[r+dr][c+dc] not in (0, 5))
    (a, b) = marks
    if nearby(*a) >= nearby(*b):
        sr, sc = a; tr, tc = b
    else:
        sr, sc = b; tr, tc = a
    dr, dc = tr-sr, tc-sc
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 5):
                rr, cc = r+dr, c+dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = v
    return out

